import{_ as o,a0 as r,w as p,s as d,I as i,x as e,a1 as l,A as a,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"在 Linux 上安裝和使用 Docker | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上安裝和使用 Docker | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上安裝和使用 Docker | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上安裝和使用 Docker | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171117 How to Install and Use Docker on Linux","title":"在 Linux 上安裝和使用 Docker","tag":"201802","desc":""},"relativePath":"201802/20171117 How to Install and Use Docker on Linux.md","filePath":"[post].md"}'),k={name:"201802/20171117 How to Install and Use Docker on Linux.md"};function u(g,s,h,c,b,f){const t=r("Link");return p(),d("div",null,[s[30]||(s[30]=i("h1",{id:"在-linux-上安裝和使用-docker",tabindex:"-1"},[e("在 Linux 上安裝和使用 Docker "),i("a",{class:"header-anchor",href:"#在-linux-上安裝和使用-docker","aria-label":"Permalink to “在 Linux 上安裝和使用 Docker”"},"​")],-1)),s[31]||(s[31]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/use-containers.jpg?itok=s3YLmYHs",alt:""})],-1)),s[32]||(s[32]=i("p",null,"容器現在風靡於 IT 界 —— 這很好理解。容器是輕量級的，包含應用運行所需所有東西（代碼、庫、運行時環境、系統設置，以及依賴關係）的獨立的包。每個容器都部署於它自己的 CPU、內存、塊 I/O，以及網絡資源上，所有這些都不依賴於某個內核和操作系統。這也是容器與虛擬機之間最大的不同；相比之下，虛擬機是一個運行於宿主機操作系統上的完整的操作系統平台，而容器不是。",-1)),s[33]||(s[33]=i("p",null,"容器允許你以一種前所未有的方式擴展交付能力（不管內部還是外部的）。例如，你可以快速部署多個 NGINX 實例（甚至可以應用於多個不同的階段 —— 比如開發和生產階段）。跟虛擬機不同，容器不會消耗太多系統資源。",-1)),i("p",null,[l(t,{href:"https://www.docker.com/"},{default:a(()=>[...s[0]||(s[0]=[e("Docker",-1)])]),_:1}),s[1]||(s[1]=e(" 使得創建、部署，和管理容器變得特別簡單。更好的是，安裝和使用 Docker 在 Linux 平台上特別的方便。",-1))]),i("p",null,[s[3]||(s[3]=e("我將會向你演示在 Linux 上安裝 Docker 是多麼方便，同時帶你入門 Docker。我的演示平台是 ",-1)),l(t,{href:"http://releases.ubuntu.com/16.04/"},{default:a(()=>[...s[2]||(s[2]=[e("Ubuntu 16.04 Server",-1)])]),_:1}),s[4]||(s[4]=e("，但流程在大多數其它 Linux 平台都差不多。",-1))]),s[34]||(s[34]=n('<p>我這裏假設你已經啓動了 Ubuntu Server 16.04。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>由於 Ubuntu Server 16.04 缺少圖形界面，我會完全通過命令列來安裝和使用 Docker。在你安裝前，你需要更新 <code>apt</code> 然後進行必要的升級。一定要注意，若系統內核升級了，你會需要重啓系統。因此最好挑個服務器能重啓的時間進行。</p><p>運行下面命令更新 <code>apt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>完成後，使用命令升級系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt upgrade</span></span></code></pre></div><p>若內核升級了，你需要用下面命令重啓服務器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo reboot</span></span></code></pre></div><p>若內核沒有升級，你就可以安裝 Docker 了（無需重啓）。安裝 Docker 的命令為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install docker.io</span></span></code></pre></div>',11)),i("p",null,[s[6]||(s[6]=e("若你使用的是其它 Linux 發行版，當嘗試用相應的包管理器來安裝時卻發現沒有 ",-1)),s[7]||(s[7]=i("code",null,"docker.io",-1)),s[8]||(s[8]=e(" 包，則你應該安裝 ",-1)),s[9]||(s[9]=i("code",null,"docker",-1)),s[10]||(s[10]=e(" 包。例如，在 ",-1)),l(t,{href:"https://getfedora.org/"},{default:a(()=>[...s[5]||(s[5]=[e("Fedora",-1)])]),_:1}),s[11]||(s[11]=e(" 上安裝應該用命令：",-1))]),s[35]||(s[35]=n(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install docker</span></span></code></pre></div><p>若你使用的是 CentOS 7，那麼最好使用安裝腳本來安裝 docker。首先使用命令 <code>sudo yum check-update</code> 更新系統。升級完後，輸入下面命令來下載並運行所需的腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>curl -fsSL https://get.docker.com/ | sh</span></span></code></pre></div><p>默認情況下，只有管理員權限能夠運行 docker 命令。考慮到安全問題，你不會想用 root 用户或使用 <code>sudo</code> 來運行 Docker 的。要解決這個問題，你需要將自己的用户加入到 docker 組中。命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo usermod -a -G docker $USER</span></span></code></pre></div><p>完成操作後，登出系統然後再重新登錄，應該就搞定了。不過若你的平台是 Fedora，則添加用户到 docker 組時會發現這個組是不存在的。那該怎麼辦呢？你需要首先創建這個組。命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo groupadd docker &amp;&amp; sudo gpasswd -a \${USER} docker &amp;&amp; sudo systemctl restart docker</span></span>
<span class="line"><span>newgrp docker</span></span></code></pre></div><p>登出後再登錄。就可以開始用 Docker 了。</p><h3 id="啓動-暫停以及啓用-docker" tabindex="-1">啓動，暫停以及啓用 Docker <a class="header-anchor" href="#啓動-暫停以及啓用-docker" aria-label="Permalink to “啓動，暫停以及啓用 Docker”">​</a></h3><p>安裝好 Docker 後，你可以讓系統在啓動時自動啓動 Docker 守護進程。使用下面兩個命令來實現這一點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl start docker</span></span>
<span class="line"><span>sudo systemctl enable docker</span></span></code></pre></div><p>若需要暫停或重啓 Docker 守護進程，則命令為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl stop docker</span></span>
<span class="line"><span>sudo systemctl restart docker</span></span></code></pre></div><p>現在可以用 Docker 來部署容器了。</p><h3 id="拉取鏡像" tabindex="-1">拉取鏡像 <a class="header-anchor" href="#拉取鏡像" aria-label="Permalink to “拉取鏡像”">​</a></h3>`,15)),i("p",null,[s[14]||(s[14]=e("對 Docker 來説，鏡像是構建容器的基石。你可以拉下一個鏡像（比如 ",-1)),l(t,{href:"https://www.nginx.com/"},{default:a(()=>[...s[12]||(s[12]=[e("NGINX",-1)])]),_:1}),s[15]||(s[15]=e("）然後根據這個鏡像部署任意多個容器出來。使用鏡像前，你首先需要把鏡像拉取到系統中。鏡像從註冊倉庫中拉取，默認情況下安裝好的 Docker 包含了一個默認的註冊倉庫 ",-1)),l(t,{href:"https://hub.docker.com/"},{default:a(()=>[...s[13]||(s[13]=[e("Docker Hub",-1)])]),_:1}),s[16]||(s[16]=e(" —— 這個註冊倉庫包含了大量別人所貢獻的鏡像（既包括官方的鏡像，也包括用户自己貢獻的鏡像）。",-1))]),s[36]||(s[36]=n('<p>假設你想要拉取一個 Nginx Web 服務器相關的鏡像。在開始拉取前，先檢查一下系統中已經有了哪些鏡像。輸入 <code>docker images</code> 命令你會發現現在還沒有鏡像存在（圖 1）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/docker_1.jpg?itok=CxSyyXyF" alt="Docker" title="Docker"></p><p><em>圖 1：還沒有鏡像。</em></p><p>讓我們來拉取一個鏡像。使用下面命令可以從 Docker Hub 中下載 Nginx 鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker pull nginx</span></span></code></pre></div><p>上面命令會從 Docker Hub 下載最新的（官方的） Nginx 鏡像。現在再運行 <code>docker images</code> 命令就能看到有列出鏡像了（圖 2）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/docker_2.jpg?itok=TESa7bYr" alt="Docker" title="Docker"></p><p><em>圖 2：NGINX 鏡像已經被拉取下來了。</em></p><p>注意到我這裏説的是“官方” Nginx 鏡像了嗎？在 Docker Hub 上有很多的非官方 Nginx 鏡像。這些非官方鏡像都是基於各種不同的目的而創建出來的。你可以使用下面過命令來搜索 Docker Hub 中的所有 Nginx 鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker search nginx</span></span></code></pre></div><p>你會發現（圖 3 中），有很多基於不同目的所創建的 Nginx 鏡像（反向代理、PHP-FPM（LCTT 譯註：<ruby>FastCGI 進程管理器<rt>FastCGI Process Manager</rt></ruby>是一個 PHPFastCGI 管理器，旨在將 FastCGI 進程管理整合進 PHP 包中）功能、LetsEncrypt（LCTT 譯註：由 ISRG 提供的免費 SSL 項目），Bitnami，在樹莓派上使用的 Nginx 和 Drupal，等等很多很多)。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/docker_3.jpg?itok=_7F4QWqx" alt="Docker hub" title="Docker hub"></p><p><em>圖 3：Docker Hub 上找到的各種 NGINX 鏡像。</em></p><p>假設，你想要下載內建有反向代理功能的 Nginx 鏡像，有個非官方的鏡像 jwilder/nginx-proxy。因此輸入下面命令來拉取這個鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>docker pull jwilder/nginx-proxy</span></span></code></pre></div><p>再輸入 <code>docker images</code> 命令來查看新拉下來的這個鏡像（圖 4）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/docker_4.jpg?itok=f13E1L0Q" alt="Nginx" title="Nginx"></p><p><em>圖 4：已經有了兩種不同的 NGINX 鏡像了。</em></p><p>處於謹慎考慮，我建議只使用官方鏡像，畢竟你無法確定非官方鏡像是否包含了惡意代碼。</p><p>有了鏡像後就可以用它來部署容器了。下次我們再聊聊如何通過這些 Nginx 鏡像來發布容器。</p><p>Docker 是一個超級強力的系統可以讓你的工作更簡單，讓你的公司更具有伸縮性，也更靈活。想知道 Docker 還能做什麼，運行 <code>man docker</code> 然後閲讀它的幫助文檔吧。</p><hr>',22)),i("p",null,[s[18]||(s[18]=e("via: ",-1)),l(t,{href:"https://www.linux.com/learn/intro-to-linux/2017/11/how-install-and-use-docker-linux"},{default:a(()=>[...s[17]||(s[17]=[e("https://www.linux.com/learn/intro-to-linux/2017/11/how-install-and-use-docker-linux",-1)])]),_:1})]),i("p",null,[s[22]||(s[22]=e("作者：",-1)),l(t,{href:"https://www.linux.com/users/jlwallen"},{default:a(()=>[...s[19]||(s[19]=[e("Jack Wallen",-1)])]),_:1}),s[23]||(s[23]=e(" 譯者：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[20]||(s[20]=[e("lujun9972",-1)])]),_:1}),s[24]||(s[24]=e(" 校對：",-1)),l(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[21]||(s[21]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[27]||(s[27]=e("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[25]||(s[25]=[e("LCTT",-1)])]),_:1}),s[28]||(s[28]=e(" 原創編譯，",-1)),l(t,{href:"https://linux.cn/"},{default:a(()=>[...s[26]||(s[26]=[e("Linux中國",-1)])]),_:1}),s[29]||(s[29]=e(" 榮譽推出",-1))])])}const C=o(k,[["render",u]]);export{y as __pageData,C as default};
